import json, sys, time
from concurrent.futures import ProcessPoolExecutor, as_completed
sys.path.insert(0,'/app/code')

def one(eid):
 from allensdk.brain_observatory.behavior.behavior_project_cache import VisualBehaviorOphysProjectCache
 c=VisualBehaviorOphysProjectCache.from_s3_cache(cache_dir='/app/data')
 e=c.get_behavior_ophys_experiment(eid)
 tr=e.trials
 flags={k:int(tr[k].fillna(False).sum()) for k in ['go','catch','hit','miss','false_alarm','correct_reject','aborted','auto_rewarded']}
 valid=(~tr.aborted.fillna(False)) & (~tr.auto_rewarded.fillna(False)) & (tr.go.fillna(False)|tr.catch.fillna(False))
 return {'id':eid,'neurons':len(e.cell_specimen_table),'trials':len(tr),'valid_trials':int(valid.sum()),**flags}

if __name__=='__main__':
 ids=json.load(open('/app/data/active_experiment_ids.json')); out=[]; failures=[]; st=time.time()
 with ProcessPoolExecutor(max_workers=4) as ex:
  fs={ex.submit(one,x):x for x in ids}
  for j,f in enumerate(as_completed(fs),1):
   try: out.append(f.result())
   except Exception as e: failures.append((fs[f],type(e).__name__,str(e)))
   if j%20==0: print(f'progress {j}/{len(ids)} elapsed={time.time()-st:.1f}s',flush=True)
 out.sort(key=lambda z:z['id']); json.dump({'records':out,'failures':failures},open('/app/data/step2_census.json','w'))
 import numpy as np
 print('completed',len(out),'failures',failures)
 for k in ['neurons','trials','valid_trials','go','catch','hit','miss','false_alarm','correct_reject','aborted','auto_rewarded']:
  a=np.array([r[k] for r in out]); print(k,'total',int(a.sum()),'mean',float(a.mean()),'min',int(a.min()),'max',int(a.max()))
 print('elapsed_seconds',time.time()-st)
